UPDATE user_daily_usage
SET upload_count = upload_count + 1
WHERE user_id = #{userId}
  AND stat_date = #{statDate}
  AND upload_count < #{limit}

UPDATE user_daily_usage
SET token_count = token_count + #{tokens}
WHERE user_id = #{userId}
  AND stat_date = #{statDate}
  AND token_count + #{tokens} <= #{limit}
